import type { GameStage_Serialize, Status_Serialize } from "@/bindings";

/// A status with safe defaults, for tests that need one game state without a backend. The stage is the only stateful
/// part; every other field is ready and empty, so a test names only the fields its selector reads.
export function statusFixture(stage: GameStage_Serialize, overrides: Partial<Status_Serialize> = {}): Status_Serialize {
	return {
		game_name: "Game",
		game_subtitle: "",
		runtime: "steam_proton",
		stage,
		next_action: "apply",
		blocker: null,
		settings: {
			game_root: "/games/Game",
			settings_dir: "/games/Game",
			mods_root: "",
			proton_dir: "",
			launch_env: "",
			launch_args: "",
			profile_data: [],
			proton_options: [],
			proton_fps_limit: null,
			source: "steam",
			prefix_dir: "",
		},
		game_ready: true,
		settings_ready: true,
		needs_mods_root: false,
		mods_ready: true,
		mods_root: "/games/Game",
		needs_settings_dir: false,
		deployed: false,
		draft_changes: 0,
		deployed_at: null,
		deployed_list: [],
		profiles: [],
		mods: [],
		revisions: [],
		build: 0,
		patch: false,
		removed: [],
		order: null,
		separators: [],
		groups: [],
		history: { can_undo: false, can_redo: false },
		bisect: null,
		has_overwrite: false,
		conflict_count: 0,
		problems: [],
		warnings: [],
		library_dir: "/data/library",
		archives_dir: "/data/archives",
		profile_dir: null,
		overwrite_dir: "/data/state/p1/overwrite",
		game_profile_data: [],
		user_data: [],
		launch_hint: "",
		executables: [],
		tools: [],
		...overrides,
	};
}
